import React from "react";
import { Route, Routes, useLocation, Navigate } from "react-router-dom";
import { useAuth } from "./context/AuthContext.jsx";
import Navbar from "./components/Navbar.jsx";
import Footer from "./components/Footer.jsx";
import Landing from "./pages/Landing.jsx";
import Marketplace from "./pages/Marketplace.jsx";
import ItemDetails from "./pages/ItemDetails.jsx";
import AddListing from "./pages/AddListing.jsx";
import Booking from "./pages/Booking.jsx";
import MyBookings from "./pages/MyBookings.jsx";
import Chat from "./pages/Chat.jsx";
import Login from "./pages/Login.jsx";
import Signup from "./pages/Signup.jsx";
import DashboardLayout from "./components/DashboardLayout.jsx";
import Profile from "./pages/Profile.jsx";
import MyListings from "./pages/MyListings.jsx";
import NotFound from "./pages/NotFound.jsx";
import { ChatProvider } from "./context/ChatContext.jsx";

function ProtectedRoute({ children }) {
  const { user } = useAuth();
  if (!user) {
    return <Navigate to="/login" replace />;
  }
  return children;
}

function App() {
  const location = useLocation();

  return (
    <div className="page">
      <Navbar />
      <main className="page-body">
        <div key={location.pathname} className="page-transition">
          <Routes location={location}>
            <Route path="/" element={<Landing />} />
            <Route path="/login" element={<Login />} />
            <Route path="/signup" element={<Signup />} />
            <Route path="/marketplace" element={<ProtectedRoute><Marketplace /></ProtectedRoute>} />
            <Route path="/item/:id" element={<ProtectedRoute><ItemDetails /></ProtectedRoute>} />
            <Route path="/add" element={<ProtectedRoute><AddListing /></ProtectedRoute>} />
            <Route path="/booking/:id" element={<ProtectedRoute><Booking /></ProtectedRoute>} />
            <Route path="/my-bookings" element={<ProtectedRoute><MyBookings /></ProtectedRoute>} />
            <Route path="/chat" element={<ProtectedRoute><ChatProvider><Chat /></ChatProvider></ProtectedRoute>} />
            <Route path="/user/:id" element={<Profile />} />

            <Route path="/dashboard" element={<ProtectedRoute><DashboardLayout /></ProtectedRoute>}>
              <Route path="profile" element={<Profile />} />
              <Route path="rentals" element={<MyBookings />} />
              <Route path="listings" element={<MyListings />} />
            </Route>

            <Route path="*" element={<NotFound />} />
          </Routes>
        </div>
      </main>
      <Footer />
    </div>
  );
}

export default App;

import React from "react";
import { BOOKING_STATUS } from "../constants/bookingStatus.js";

function ApprovalCard({ approval, onApprove, onReject }) {
  const isApproved = approval.status === BOOKING_STATUS.approved;

  return (
    <div
      style={{
        padding: "18px",
        borderRadius: "16px",
        border: "1px solid var(--border, #e5e7eb)",
        background: "var(--surface, #ffffff)",
        display: "grid",
        gridTemplateColumns: "1fr auto",
        gap: "16px",
      }}
    >
      <div>
        <h4 style={{ margin: 0, fontSize: "16px", fontWeight: 700 }}>{approval.title}</h4>
        <p style={{ margin: "6px 0 0", color: "var(--muted, #6b7280)" }}>
          Requested by {approval.requester} · {approval.dates}
        </p>
      </div>
      {isApproved ? (
        <span
          style={{
            alignSelf: "center",
            padding: "6px 12px",
            borderRadius: "999px",
            fontSize: "12px",
            fontWeight: 600,
            background: "rgba(16, 185, 129, 0.12)",
            color: "var(--primary, #0d9488)",
            border: "1px solid rgba(16, 185, 129, 0.25)",
          }}
        >
          Approved
        </span>
      ) : (
        <div style={{ display: "flex", gap: "8px", alignItems: "center" }}>
          <button className="btn outline" style={{ padding: "6px 12px", fontSize: "13px" }} onClick={() => onApprove?.(approval)}>
            Approve
          </button>
          <button
            className="btn outline"
            style={{ padding: "6px 12px", fontSize: "13px", borderColor: "#e11d48", color: "#e11d48" }}
            onClick={() => onReject?.(approval)}
          >
            Reject
          </button>
        </div>
      )}
    </div>
  );
}

export default ApprovalCard;

import React from "react";

function BookingForm({ startDate, endDate, onStartChange, onEndChange, error, totalDays }) {
  const todayStr = new Date().toISOString().split('T')[0];

  return (
    <div className="booking-form" style={{ background: 'var(--surface)', border: '1px solid var(--border)', borderRadius: '16px', padding: '32px', boxShadow: 'var(--shadow)' }}>
      <h3 style={{ fontSize: '20px', fontWeight: 600, marginBottom: '24px' }}>Select Rental Dates</h3>

      <div style={{ display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) minmax(0, 1fr)', gap: '20px' }}>
        <div>
          <label style={{ display: 'block', fontSize: '14px', fontWeight: 600, marginBottom: '8px' }}>Pickup Date</label>
          <input 
            type="date" 
            value={startDate} 
            onChange={(e) => onStartChange(e.target.value)} 
            min={todayStr}
            style={{ width: '100%', padding: '12px 16px', borderRadius: '8px', border: '1px solid var(--border)', fontSize: '15px', outline: 'none' }}
          />
        </div>
        <div>
          <label style={{ display: 'block', fontSize: '14px', fontWeight: 600, marginBottom: '8px' }}>Return Date</label>
          <input 
            type="date" 
            value={endDate} 
            onChange={(e) => onEndChange(e.target.value)} 
            min={startDate || todayStr}
            style={{ width: '100%', padding: '12px 16px', borderRadius: '8px', border: '1px solid var(--border)', fontSize: '15px', outline: 'none' }}
          />
        </div>
      </div>

      {error && (
        <div style={{ marginTop: '16px', color: '#e11d48', fontSize: '14px', padding: '10px 14px', background: 'rgba(225, 29, 72, 0.1)', borderRadius: '8px' }}>
          ⚠️ {error}
        </div>
      )}

      {!error && totalDays > 0 && (
        <div style={{ marginTop: '16px', color: 'var(--primary)', fontSize: '14px', padding: '10px 14px', background: 'rgba(16, 185, 129, 0.1)', borderRadius: '8px', fontWeight: 500 }}>
          Rental duration: {totalDays} {totalDays === 1 ? 'day' : 'days'}
        </div>
      )}
    </div>
  );
}

export default BookingForm;

import React from "react";
import { resolveMediaDisplay } from "../utils/mediaUtils.js";

function BorrowedItemCard({
  rental,
  onPrimaryAction,
  onReportIssue,
  onChat,
  primaryActionLabel = "Mark as Returned",
  primaryActionDisabled = false,
  lifecycleNote = ""
}) {
  const media = resolveMediaDisplay(rental.image, "teal");
  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: "160px 1fr",
        gap: "20px",
        padding: "20px",
        borderRadius: "16px",
        border: "1px solid var(--border, #e5e7eb)",
        background: "var(--surface, #ffffff)",
        boxShadow: "var(--shadow)",
      }}
    >
      <div
        className={media.className}
        style={{ ...media.style, width: "160px", height: "120px", borderRadius: "12px" }}
      />

      <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
        <div>
          <h3 style={{ margin: 0, fontSize: "18px", fontWeight: 700 }}>{rental.name}</h3>
          <p style={{ margin: "6px 0 0", color: "var(--muted, #6b7280)" }}>Owner: {rental.owner}</p>
        </div>

        <div style={{ display: "grid", gap: "6px", color: "var(--muted, #6b7280)", fontSize: "14px" }}>
          <div>Rental dates: {rental.dates}</div>
          <div>Deposit: {rental.deposit}</div>
          <div>Total paid: {rental.total}</div>
          {lifecycleNote ? <div>{lifecycleNote}</div> : null}
        </div>

        <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
          <button
            className="btn primary"
            style={{ padding: "8px 14px", fontSize: "14px" }}
            onClick={() => onPrimaryAction?.(rental)}
            disabled={primaryActionDisabled}
          >
            {primaryActionLabel}
          </button>
          <button
            className="btn outline"
            style={{ padding: "8px 14px", fontSize: "14px", borderColor: "#e11d48", color: "#e11d48" }}
            onClick={() => onReportIssue?.(rental)}
          >
            Report Issue
          </button>
          <button
            className="btn outline"
            style={{ padding: "8px 14px", fontSize: "14px" }}
            onClick={() => onChat?.(rental)}
          >
            Chat with Owner
          </button>
        </div>
      </div>
    </div>
  );
}

export default BorrowedItemCard;

import React from "react";
import { resolveMediaDisplay } from "../utils/mediaUtils.js";

function CompletedRentalCard({ rental, onRateOwner }) {
  const statusLabel = rental.statusLabel || "Completed";
  const isCompleted = statusLabel.toLowerCase() === "completed";
  const statusStyle = isCompleted
    ? {
        background: "rgba(16, 185, 129, 0.12)",
        color: "var(--primary, #0d9488)",
        border: "1px solid rgba(16, 185, 129, 0.25)",
      }
    : statusLabel.toLowerCase() === "cancelled"
      ? {
          background: "rgba(245, 158, 11, 0.12)",
          color: "#b45309",
          border: "1px solid rgba(245, 158, 11, 0.25)",
        }
      : {
          background: "rgba(239, 68, 68, 0.12)",
          color: "#b91c1c",
          border: "1px solid rgba(239, 68, 68, 0.25)",
        };

  const media = resolveMediaDisplay(rental.image, "teal");
  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: "160px 1fr",
        gap: "20px",
        padding: "20px",
        borderRadius: "16px",
        border: "1px solid var(--border, #e5e7eb)",
        background: "var(--surface, #ffffff)",
        boxShadow: "var(--shadow)",
      }}
    >
      <div
        className={media.className}
        style={{ ...media.style, width: "160px", height: "120px", borderRadius: "12px" }}
      />

      <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
        <div style={{ display: "flex", justifyContent: "space-between", gap: "12px" }}>
          <div>
            <h3 style={{ margin: 0, fontSize: "18px", fontWeight: 700 }}>{rental.name}</h3>
            <p style={{ margin: "6px 0 0", color: "var(--muted, #6b7280)" }}>Owner: {rental.owner}</p>
          </div>
          <span
            style={{
              alignSelf: "flex-start",
              padding: "6px 12px",
              borderRadius: "999px",
              fontSize: "12px",
              fontWeight: 600,
              ...statusStyle,
            }}
          >
            {statusLabel}
          </span>
        </div>

        <div style={{ display: "grid", gap: "6px", color: "var(--muted, #6b7280)", fontSize: "14px" }}>
          <div>
            {isCompleted
              ? `Returned on ${rental.returned}`
              : statusLabel.toLowerCase() === "cancelled"
                ? `Cancelled by ${rental.cancelledBy || "borrower"}`
                : "Request was rejected by lender"}
          </div>
          {rental.dates && <div>Booking dates: {rental.dates}</div>}
        </div>

        {isCompleted && (
          <div style={{ display: "flex", gap: "10px", flexWrap: "wrap" }}>
            <button
              className="btn outline"
              style={{ padding: "8px 14px", fontSize: "14px" }}
              onClick={() => onRateOwner?.(rental)}
            >
              Rate Owner
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

export default CompletedRentalCard;

import React from "react";
import { NavLink, Outlet, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext.jsx";

function DashboardLayout() {
  const navigate = useNavigate();
  const { logout } = useAuth();

  const handleLogout = () => {
    logout();
    navigate("/login");
  };

  const getNavLinkStyle = ({ isActive }) => ({
    textDecoration: "none",
    padding: "12px 16px",
    borderRadius: "8px",
    display: "block",
    backgroundColor: isActive ? "var(--primary-color, #0d9488)" : "transparent",
    color: isActive ? "#fff" : "var(--text-main, #1f2937)",
    fontWeight: isActive ? "600" : "400",
    transition: "background-color 0.2s",
  });

  return (
    <div className="dashboard-layout" style={{ display: "flex", minHeight: "calc(100vh - 70px)" }}>
      <aside
        style={{
          width: "240px",
          borderRight: "1px solid var(--border-color, #e5e7eb)",
          padding: "24px",
          display: "flex",
          flexDirection: "column",
          backgroundColor: "#fff",
        }}
      >
        <nav style={{ display: "flex", flexDirection: "column", gap: "8px", flexGrow: 1 }}>
          <NavLink to="/dashboard/profile" style={getNavLinkStyle}>
            Profile
          </NavLink>
          <NavLink to="/dashboard/rentals" style={getNavLinkStyle}>
            My Borrowings
          </NavLink>
          <NavLink to="/dashboard/listings" style={getNavLinkStyle}>
            My Listings
          </NavLink>
        </nav>

        <button
          onClick={handleLogout}
          style={{
            marginTop: "auto",
            padding: "12px 16px",
            backgroundColor: "transparent",
            color: "var(--error, #ef4444)",
            border: "1px solid var(--error, #ef4444)",
            borderRadius: "8px",
            cursor: "pointer",
            fontWeight: "600",
            textAlign: "center",
            transition: "all 0.2s",
          }}
          onMouseOver={(e) => {
            e.currentTarget.style.backgroundColor = "var(--error, #ef4444)";
            e.currentTarget.style.color = "#fff";
          }}
          onMouseOut={(e) => {
            e.currentTarget.style.backgroundColor = "transparent";
            e.currentTarget.style.color = "var(--error, #ef4444)";
          }}
        >
          Logout
        </button>
      </aside>

      <main
        style={{
          flexGrow: 1,
          padding: "32px",
          backgroundColor: "var(--bg-secondary, #f8fafc)",
          overflowY: "auto",
        }}
      >
        <Outlet />
      </main>
    </div>
  );
}

export default DashboardLayout;

import React from "react";
import { useNavigate } from "react-router-dom";
import { resolveMediaDisplay } from "../utils/mediaUtils.js";

function ItemCard({ item }) {
  const navigate = useNavigate();

  const goToDetails = () => {
    navigate(`/item/${item.id}`);
  };

  const title = item.title || item.name;
  const priceDisplay = item.pricePerDay ? `Rs ${item.pricePerDay} ` : "";
  const numReviews = item.reviewsCount ? `(${item.reviewsCount})` : "(0)";
  const badgeLabel = item.isVerified ? "Verified" : "Featured";
  const rentedUntilLabel = item.rentedUntil
    ? new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric" }).format(new Date(item.rentedUntil))
    : "";

  const isManuallyUnavailable =
    Boolean(item.isHidden) || String(item.availability || "").toLowerCase().includes("not available");
  const media = resolveMediaDisplay(item.images?.[0], "purple");

  return (
    <article
      className="marketplace-card"
      role="button"
      tabIndex={0}
      aria-label={`View details for ${title}`}
      onClick={goToDetails}
      onKeyDown={(e) => {
        if (e.key === "Enter" || e.key === " ") {
          e.preventDefault();
          goToDetails();
        }
      }}
    >
      <div className={media.className} style={media.style}>
        <span className="marketplace-card-badge">{badgeLabel}</span>
      </div>

      <div className="marketplace-card-body">
        <h3 className="marketplace-card-title">{title}</h3>
        <div className="marketplace-card-location">{item.location}</div>
        {rentedUntilLabel && (
          <div
            style={{
              marginTop: "8px",
              marginBottom: "8px",
              fontSize: "12px",
              fontWeight: 600,
              color: "var(--muted)",
            }}
          >
            Rented until {rentedUntilLabel}
          </div>
        )}

        <div className="marketplace-card-price-row">
          <div className="marketplace-card-price">
            {priceDisplay}
            {item.pricePerDay && <span>/ day</span>}
          </div>
          <div className="marketplace-rating-info">
            {item.rating || "4.8"} <span className="reviews">{numReviews}</span>
          </div>
        </div>

        <div className="marketplace-card-actions">
          <button
            type="button"
            className="btn primary"
            disabled={isManuallyUnavailable}
            onClick={(e) => {
              e.stopPropagation();
              if (isManuallyUnavailable) return;
              navigate(`/booking/${item.id}`);
            }}
          >
            Rent Now
          </button>
          <button
            type="button"
            className="btn outline"
            onClick={(e) => {
              e.stopPropagation();
              goToDetails();
            }}
          >
            View Details
          </button>
        </div>
      </div>
    </article>
  );
}

export default ItemCard;

import React, { useState } from "react";
import { resolveMediaDisplay } from "../utils/mediaUtils.js";

function ItemGallery({ images = [], fallbackClass = "purple" }) {
  const [activeIndex, setActiveIndex] = useState(0);

  const mainImage = images.length > 0 ? images[activeIndex] : fallbackClass;
  const mainMedia = resolveMediaDisplay(mainImage, fallbackClass || "purple");

  return (
    <div className="item-gallery">
      {/* Main Large Image */}
      <div 
        className={`${mainMedia.className} skeleton-bg`} 
        style={{ 
          ...mainMedia.style,
          width: '100%', 
          aspectRatio: '4/3', 
          borderRadius: '16px',
          border: '1px solid var(--border)',
          boxShadow: 'var(--shadow)',
          marginBottom: '16px',
          transition: 'background 0.3s ease'
        }}
      ></div>

      {/* Thumbnails */}
      {images.length > 1 && (
        <div style={{ display: 'flex', gap: '12px', overflowX: 'auto', paddingBottom: '8px' }}>
          {images.map((imgClass, idx) => {
            const thumbMedia = resolveMediaDisplay(imgClass, fallbackClass || "purple");
            return (
            <div 
              key={idx}
              onClick={() => setActiveIndex(idx)}
              className={thumbMedia.className}
              style={{ 
                ...thumbMedia.style,
                flexShrink: 0,
                width: '80px', 
                height: '80px', 
                borderRadius: '10px', 
                cursor: 'pointer',
                border: idx === activeIndex ? '2px solid var(--primary)' : '1px solid var(--border)',
                opacity: idx === activeIndex ? 1 : 0.6,
                transition: 'all 0.2s ease',
                transform: idx === activeIndex ? 'scale(1.05)' : 'scale(1)'
              }}
            ></div>
          )})}
        </div>
      )}
    </div>
  );
}

export default ItemGallery;

import React from "react";

function ItemInfo({ item }) {
  const badgeLabel = item.isVerified ? "Verified Student" : "Student Listing";
  const numReviews = item.reviewsCount ? `(${item.reviewsCount} reviews)` : `(0 reviews)`;

  return (
    <div className="item-info">
      {/* Title & Meta Header */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '12px', marginBottom: '8px' }}>
        <span style={{ 
          padding: '6px 12px', 
          background: item.isVerified ? 'rgba(16, 185, 129, 0.1)' : 'rgba(99, 102, 241, 0.1)', 
          color: item.isVerified ? 'var(--primary)' : 'var(--accent)', 
          borderRadius: '999px', fontSize: '13px', fontWeight: 600 
        }}>
          {badgeLabel}
        </span>
        <span style={{ fontSize: '14px', color: 'var(--muted)', display: 'flex', alignItems: 'center', gap: '4px' }}>
          📍 {item.location}
        </span>
      </div>

      <h1 style={{ fontSize: '32px', fontWeight: 800, lineHeight: 1.2, marginBottom: '16px' }}>
        {item.title}
      </h1>

      <div style={{ display: 'flex', alignItems: 'flex-end', gap: '16px', marginBottom: '8px' }}>
        <div style={{ fontSize: '36px', fontWeight: 800, color: 'var(--primary)', lineHeight: 1 }}>
          ₹{item.pricePerDay} <span style={{ fontSize: '16px', color: 'var(--muted)', fontWeight: 500 }}>/ day</span>
        </div>
      </div>

      <div style={{ display: 'flex', alignItems: 'center', gap: '6px', fontSize: '15px' }}>
        <span style={{ color: '#b46a00' }}>⭐ {item.rating || "0.0"}</span>
        <span style={{ color: 'var(--muted)' }}>{numReviews}</span>
      </div>

      <hr style={{ border: 'none', borderTop: '1px solid var(--border)', margin: '24px 0' }} />

      {/* Description Body */}
      <div>
        <h3 style={{ fontSize: '18px', fontWeight: 700, marginBottom: '12px' }}>Description</h3>
        <p style={{ color: 'var(--muted)', lineHeight: 1.6, fontSize: '15px' }}>
          {item.description || "No description provided."}
        </p>
      </div>

      {/* Specs Grid */}
      <div style={{ 
        display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '16px', 
        background: 'var(--surface)', padding: '16px', borderRadius: '12px', 
        border: '1px solid var(--border)', marginTop: '24px' 
      }}>
        <div>
          <span style={{ display: 'block', fontSize: '13px', color: 'var(--muted)', marginBottom: '4px' }}>Category</span>
          <span style={{ fontWeight: 600 }}>{item.category || "General"}</span>
        </div>
        <div>
          <span style={{ display: 'block', fontSize: '13px', color: 'var(--muted)', marginBottom: '4px' }}>Availability</span>
          <span style={{ 
            fontWeight: 600, 
            color: item.availability === "Available Now" ? 'var(--primary)' : 'var(--muted)', 
            display: 'flex', alignItems: 'center', gap: '6px' 
          }}>
            <span style={{ 
              width: '8px', height: '8px', borderRadius: '50%', 
              background: item.availability === "Available Now" ? 'var(--primary)' : 'var(--muted)' 
            }}></span>
            {item.availability || "Unknown"}
          </span>
        </div>
      </div>
    </div>
  );
}

export default ItemInfo;

﻿import React from "react";
import { resolveMediaDisplay } from "../utils/mediaUtils.js";

const statusStyles = {
  Available: {
    background: "rgba(16, 185, 129, 0.12)",
    color: "var(--primary, #0d9488)",
    border: "1px solid rgba(16, 185, 129, 0.25)",
  },
  Rented: {
    background: "rgba(99, 102, 241, 0.12)",
    color: "var(--accent, #6366f1)",
    border: "1px solid rgba(99, 102, 241, 0.25)",
  },
  Hidden: {
    background: "rgba(107, 114, 128, 0.12)",
    color: "#6b7280",
    border: "1px solid rgba(107, 114, 128, 0.25)",
  },
};

function ListingCard({
  item,
  onEdit,
  onToggleHidden,
  onDelete,
  onConfirmReturn,
  onMarkItemGiven,
  onCancelUpcoming
}) {
  const badgeStyle = statusStyles[item.status] || statusStyles.Available;
  const hasUpcoming = item.upcoming?.length > 0;
  const media = resolveMediaDisplay(item.image, "teal");

  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: "160px 1fr",
        gap: "20px",
        padding: "20px",
        borderRadius: "16px",
        border: "1px solid var(--border, #e5e7eb)",
        background: "var(--surface, #ffffff)",
        boxShadow: "var(--shadow)",
      }}
    >
      <div
        className={media.className}
        style={{ ...media.style, width: "160px", height: "120px", borderRadius: "12px" }}
      />

      <div style={{ display: "flex", flexDirection: "column", gap: "12px" }}>
        <div style={{ display: "flex", alignItems: "flex-start", justifyContent: "space-between" }}>
          <div>
            <h3 style={{ margin: 0, fontSize: "18px", fontWeight: 700 }}>{item.name}</h3>
