﻿import React, { useEffect, useRef, useState } from "react";
import { useNavigate, useParams, useLocation } from "react-router-dom";
import BookingForm from "../components/BookingForm.jsx";
import PriceBreakdown from "../components/PriceBreakdown.jsx";
import { checkAvailability } from "../utils/bookingUtils.js";
import { BOOKING_STATUS } from "../constants/bookingStatus.js";
import { useBookings } from "../context/BookingContext.jsx";
import { useListings } from "../context/ListingContext.jsx";
import { api } from "../services/api.js";
import { resolveMediaDisplay } from "../utils/mediaUtils.js";

function Booking() {
  const { id } = useParams();
  const navigate = useNavigate();
  const location = useLocation();
  const stateContext = location.state || {};
  const { listings, isLoading: areListingsLoading } = useListings();

  const item = listings.find((entry) => String(entry.id) === String(id));

  const [startDate, setStartDate] = useState(stateContext.startDate || "");
  const [endDate, setEndDate] = useState(stateContext.endDate || "");
  const [error, setError] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const submitGuardRef = useRef(false);
  const { bookings, refreshBookings } = useBookings();

  useEffect(() => {
    if (!startDate) {
      const today = new Date().toISOString().split("T")[0];
      setStartDate(today);
    }
  }, [startDate]);

  if (areListingsLoading && !item) {
    return (
      <section
        className="page"
        style={{
          minHeight: "60vh",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <p style={{ color: "var(--muted)", fontSize: "18px" }}>Loading booking details...</p>
      </section>
    );
  }

  if (!item) {
    return (
      <section
        className="page"
        style={{
          minHeight: "60vh",
          display: "flex",
          flexDirection: "column",
          alignItems: "center",
          justifyContent: "center",
        }}
      >
        <h2 style={{ fontSize: "32px", marginBottom: "16px" }}>Item not found</h2>
        <p style={{ color: "var(--muted)", marginBottom: "24px" }}>
          Cannot proceed with booking. This item may have been removed.
        </p>
        <button onClick={() => navigate("/marketplace")} className="btn primary">
          Back to Marketplace
        </button>
      </section>
    );
  }

  const calculateTotalDays = () => {
    if (!startDate || !endDate) return 0;
    const d1 = new Date(startDate);
    const d2 = new Date(endDate);

    d1.setHours(0, 0, 0, 0);
    d2.setHours(0, 0, 0, 0);

    const diffTime = d2.getTime() - d1.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    return diffDays >= 0 ? diffDays + 1 : 0;
  };

  const validateDates = (start, end) => {
    setError("");
    if (start && end) {
      const d1 = new Date(start);
      const d2 = new Date(end);
      d1.setHours(0, 0, 0, 0);
      d2.setHours(0, 0, 0, 0);
      if (d2 < d1) {
        setError("Return date cannot be before pickup date.");
        return false;
      }

      const activeBookings = bookings.filter(
        (booking) =>
          String(booking.itemId) === String(item.id) &&
          (booking.status === BOOKING_STATUS.approved || booking.status === BOOKING_STATUS.itemGiven || booking.status === BOOKING_STATUS.ongoing || booking.status === BOOKING_STATUS.returnPending)
      );
      const availability = checkAvailability(start, end, activeBookings);
      if (!availability.isAvailable) {
        setError(`Item is already booked from ${availability.conflict.start} to ${availability.conflict.end}.`);
        return false;
      }
    }
    return true;
  };

  const handleStartChange = (val) => {
    setStartDate(val);
    validateDates(val, endDate);
  };

  const handleEndChange = (val) => {
    setEndDate(val);
    validateDates(startDate, val);
  };

  const totalDays = calculateTotalDays();
  const totalItemPrice = totalDays * item.pricePerDay;
  const serviceFee = totalDays > 0 ? 50 : 0;
  const finalTotal = totalItemPrice + serviceFee + (item.securityDeposit || 0);
  const isValid = totalDays > 0 && !error;
  const canSubmit = isValid && !isSubmitting;
  const media = resolveMediaDisplay(item.images?.[0], "purple");

  const handleConfirm = async () => {
    if (!isValid || submitGuardRef.current) return;

    submitGuardRef.current = true;
    setIsSubmitting(true);

    try {
      const response = await api.createBooking({
        listingId: item.id,
        startDate: startDate,
        endDate: endDate,
        pickupZone: item.location || "Default Zone"
      });

      if (response.success) {
        await refreshBookings();
        navigate("/chat", { state: { bookingRef: response.data.id } });
      }
    } catch (err) {
      console.error("Booking failed:", err);
      submitGuardRef.current = false;
      setIsSubmitting(false);

      if (err.status === 409) {
        setError(err.message || "Requested dates overlap with an existing booking.");
      } else {
        setError(err.message || "An unexpected error occurred while booking. Please try again.");
      }
    }
  };

  const handleCancel = () => {
    navigate(-1);
  };

  return (
    <section className="page" style={{ paddingTop: "24px" }}>
      <div style={{ marginBottom: "32px" }}>
        <button
          onClick={() => navigate(-1)}
          style={{
            background: "transparent",
            border: "none",
            cursor: "pointer",
            color: "var(--primary)",
            fontWeight: 600,
            display: "flex",
            alignItems: "center",
            gap: "4px",
            marginBottom: "16px",
          }}
        >
          <span>â†</span> Back
        </button>
        <h1 style={{ fontSize: "32px", fontFamily: '"Space Grotesk", sans-serif', marginTop: "8px" }}>
          Confirm Your Reservation
        </h1>
        <p style={{ color: "var(--muted)", fontSize: "16px", marginTop: "8px" }}>
          Review the final details before securing this rental.
        </p>
      </div>

      <div
        className="booking-layout"
        style={{
          display: "grid",
          gridTemplateColumns: "minmax(300px, 400px) minmax(0, 1fr)",
          gap: "48px",
          alignItems: "start",
        }}
      >
        <div
          style={{
            background: "var(--surface)",
            border: "1px solid var(--border)",
            borderRadius: "16px",
            overflow: "hidden",
            boxShadow: "var(--shadow)",
            position: "sticky",
            top: "100px",
          }}
        >
          <div className={media.className} style={{ ...media.style, aspectRatio: "16/9" }}></div>
          <div style={{ padding: "24px" }}>
            <h3 style={{ fontSize: "20px", fontWeight: 700, marginBottom: "8px" }}>{item.title}</h3>
            <p
              style={{
                color: "var(--muted)",
                fontSize: "14px",
                display: "flex",
                alignItems: "center",
                gap: "4px",
                marginBottom: "16px",
              }}
            >
              ðŸ“ {item.location}
            </p>
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                padding: "16px",
                background: "var(--bg)",
                borderRadius: "12px",
              }}
            >
              <span style={{ fontWeight: 600 }}>Rate</span>
              <div style={{ fontSize: "18px", fontWeight: 700, color: "var(--primary)" }}>
                â‚¹{item.pricePerDay} <span style={{ fontSize: "14px", color: "var(--muted)", fontWeight: 400 }}>/ day</span>
              </div>
            </div>
          </div>
        </div>

        <div style={{ display: "flex", flexDirection: "column", gap: "24px" }}>
          <BookingForm
            startDate={startDate}
            endDate={endDate}
            onStartChange={handleStartChange}
            onEndChange={handleEndChange}
            error={error}
            totalDays={totalDays}
          />
          <PriceBreakdown
            totalDays={totalDays}
            pricePerDay={item.pricePerDay}
            securityDeposit={item.securityDeposit}
            serviceFee={serviceFee}
            finalTotal={finalTotal}
            isValid={canSubmit}
            onConfirm={handleConfirm}
            onCancel={handleCancel}
            primaryText={isSubmitting ? "Submitting..." : "Confirm Booking"}
          />
        </div>
      </div>
    </section>
  );
}

export default Booking;

import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useAuth } from "../context/AuthContext.jsx";
import { useChat } from "../context/ChatContext.jsx";
import { sendMessage, joinConversation, leaveConversation, emitTypingStart, emitTypingStop, getSocket } from "../services/chat.js";

const formatTime = (dateStr) => {
  if (!dateStr) return "";
  const date = new Date(dateStr);
  return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
};

const formatDate = (dateStr) => {
  if (!dateStr) return "";
  const date = new Date(dateStr);
  const today = new Date();
  const yesterday = new Date(today);
  yesterday.setDate(yesterday.getDate() - 1);

  if (date.toDateString() === today.toDateString()) return "Today";
  if (date.toDateString() === yesterday.toDateString()) return "Yesterday";
  return date.toLocaleDateString([], { month: "short", day: "numeric", year: "numeric" });
};

// Debounce threshold for emitting typing:start (don't re-emit within this window)
const TYPING_DEBOUNCE_MS = 2000;
// Inactivity timeout for auto-stopping typing on the client side
const TYPING_INACTIVITY_MS = 3000;

function Chat() {
  const { user } = useAuth();

  const {
    conversations,
    activeConversation,
    activeConversationId,
    messages,
    isLoading,
    hasMore,
    isFetchingConversations,
    unreadCounts,
    typingUsers,
    onlineUsers,
    selectConversation,
    loadOlderMessages,
    refreshConversations
  } = useChat();

  const [draft, setDraft] = useState("");
  const [search, setSearch] = useState("");
  const [sending, setSending] = useState(false);
  const [sendError, setSendError] = useState(null);
  const sendErrorTimerRef = useRef(null);
  const endRef = useRef(null);
  const threadRef = useRef(null);
  const joinedRef = useRef(false);

  // Typing debounce refs
  const lastTypingEmitRef = useRef(0);
  const typingInactivityRef = useRef(null);

  // Clean up timers on unmount
  useEffect(() => {
    return () => {
      clearTimeout(typingInactivityRef.current);
      clearTimeout(sendErrorTimerRef.current);
    };
  }, []);

  useEffect(() => {
    endRef.current?.scrollIntoView({ behavior: "smooth", block: "end" });
  }, [messages]);

  // Join conversation room on selection; re-join on socket (re)connection
  useEffect(() => {
    if (!activeConversationId) return;

    const doJoin = () => {
      joinedRef.current = true;
      joinConversation(activeConversationId).catch((err) => {
        // Benign if socket not yet connected — retried on 'connect' event below
        console.error("Failed to join conversation:", err);
      });
    };

    const socket = getSocket();

    // If socket is already connected, join immediately
    if (socket?.connected) {
      doJoin();
    }

    // Re-join whenever the socket connects (initial connect AND reconnection)
    const handleConnect = () => doJoin();
    socket?.on('connect', handleConnect);

    return () => {
      socket?.off('connect', handleConnect);
      if (joinedRef.current) {
        leaveConversation(activeConversationId).catch(() => {});
        joinedRef.current = false;
      }
    };
  }, [activeConversationId]);

  const handleScroll = useCallback(() => {
    if (!threadRef.current || !hasMore || isLoading) return;
    const { scrollTop } = threadRef.current;
    if (scrollTop < 100) {
      loadOlderMessages();
    }
  }, [hasMore, isLoading, loadOlderMessages]);

  // Emit typing:start with debounce: only once per TYPING_DEBOUNCE_MS window
  // Auto-stops after TYPING_INACTIVITY_MS of inactivity
  const handleTyping = useCallback(() => {
    if (!activeConversationId) return;

    const now = Date.now();
    if (now - lastTypingEmitRef.current > TYPING_DEBOUNCE_MS) {
      lastTypingEmitRef.current = now;
      emitTypingStart(activeConversationId).catch(() => {});
    }

    // Reset inactivity timeout
    if (typingInactivityRef.current) {
      clearTimeout(typingInactivityRef.current);
    }
    typingInactivityRef.current = setTimeout(() => {
      emitTypingStop(activeConversationId).catch(() => {});
    }, TYPING_INACTIVITY_MS);
  }, [activeConversationId]);

  const handleSend = async () => {
    const text = draft.trim();
    if (!text || !activeConversationId || sending) return;

    // Stop typing before sending
    await emitTypingStop(activeConversationId).catch(() => {});
    if (typingInactivityRef.current) {
      clearTimeout(typingInactivityRef.current);
    }
    lastTypingEmitRef.current = 0;

    setSending(true);
    setSendError(null);
    try {
      await sendMessage(activeConversationId, text);
      setDraft("");
    } catch (err) {
      console.error("Failed to send message:", err);
      setSendError(err.message || "Failed to send message. Check your connection.");
      // Auto-clear error after 5 seconds; clear any previous timer first
      clearTimeout(sendErrorTimerRef.current);
      sendErrorTimerRef.current = setTimeout(() => setSendError(null), 5000);
    } finally {
      setSending(false);
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  const handleInputChange = (e) => {
    setDraft(e.target.value);
    handleTyping();
  };

  const handleSelect = (conversationId) => {
    selectConversation(conversationId);
  };

  const filteredConversations = conversations.filter((conv) => {
    if (!search) return true;
    const name = conv.otherUser?.fullName?.toLowerCase() || "";
    const title = conv.booking?.listing?.title?.toLowerCase() || "";
    const q = search.toLowerCase();
    return name.includes(q) || title.includes(q);
  });

  const groupedMessages = useMemo(() => {
    const groups = [];
    let currentDate = null;
    for (const msg of messages) {
      const msgDate = formatDate(msg.createdAt);
      if (msgDate !== currentDate) {
        currentDate = msgDate;
        groups.push({ type: "date", label: msgDate });
      }
      groups.push({ type: "message", data: msg });
    }
    return groups;
  }, [messages]);

  // Determine if the other user is typing in the active conversation
  // Compare against otherUser.id so the current user never sees themselves as typing
  const isOtherTyping = activeConversationId &&
    typingUsers[activeConversationId] &&
    typingUsers[activeConversationId] === activeConversation?.otherUser?.id;

  return (
    <section className="chat-layout" aria-label="Chat area">
      <aside className="chat-sidebar">
        <div className="chat-sidebar-head">
          <div>
            <p className="eyebrow">Messages</p>
            <h3>Campus Chat</h3>
          </div>
        </div>
        <div className="chat-search">
          <input
            type="text"
            placeholder="Search conversations..."
            aria-label="Search conversations"
            value={search}
            onChange={(e) => setSearch(e.target.value)}
          />
        </div>
        <div className="chat-list">
          {isFetchingConversations ? (
            <div className="chat-empty">
              <span style={{ opacity: 0.5 }}>Loading conversations...</span>
            </div>
          ) : filteredConversations.length === 0 ? (
            <div className="chat-empty">
              {search
                ? "No conversations match your search."
                : "No conversations yet. Start a booking to begin chatting."}
            </div>
          ) : (
            filteredConversations.map((conv) => {
              const lastMsg = conv.lastMessage;
              const preview = lastMsg
                ? lastMsg.content.length > 42
                  ? `${lastMsg.content.slice(0, 42)}...`
                  : lastMsg.content
                : "No messages yet";
              const otherUser = conv.otherUser;
              const unread = unreadCounts[conv.id] || 0;

              return (
                <button
                  key={conv.id}
                  type="button"
                  className={`chat-list-item ${conv.id === activeConversationId ? "active" : ""}`}
                  onClick={() => handleSelect(conv.id)}
                >
                  <span className="chat-avatar">
                    {otherUser?.fullName?.[0] || "?"}
                  </span>
                  <div className="chat-list-meta">
                    <strong>{otherUser?.fullName || "Unknown User"}</strong>
                    <span className="chat-list-preview">{preview}</span>
                  </div>
                  <div className="chat-list-right">
                    {unread > 0 && (
                      <span className="chat-unread-badge">{unread}</span>
                    )}
                    {conv.booking?.listing?.title && (
                      <span className="chat-list-item-label" title={conv.booking.listing.title}>
                        {conv.booking.listing.title}
                      </span>
                    )}
                  </div>
                </button>
              );
            })
          )}
        </div>
      </aside>

      <div className="chat-main">
        <header className="chat-header">
          {activeConversation ? (
            <div className="chat-user">
              <span className="chat-avatar large">
                {activeConversation.otherUser?.fullName?.[0] || "?"}
              </span>
              <div>
                <strong>{activeConversation.otherUser?.fullName || "Unknown User"}</strong>
                <span className={`chat-presence ${onlineUsers[activeConversation.otherUser?.id] ? "online" : "offline"}`}>
                  <span className="chat-presence-dot" />
                  {onlineUsers[activeConversation.otherUser?.id] ? "Online" : "Offline"}
                </span>
                {activeConversation.booking?.listing?.title && (
                  <span className="chat-status">
                    Renting: {activeConversation.booking.listing.title}
                  </span>
                )}
              </div>
            </div>
          ) : (
            <div className="chat-user">
              <div>
                <strong>No conversation selected</strong>
              </div>
            </div>
          )}
        </header>

        <div
          className="chat-thread"
          ref={threadRef}
          onScroll={handleScroll}
          role="log"
          aria-live="polite"
        >
          {isLoading && messages.length === 0 && (
            <div style={{ textAlign: "center", padding: "20px", color: "var(--muted)" }}>
              Loading messages...
            </div>
          )}

          {hasMore && (
            <div style={{ textAlign: "center", padding: "10px" }}>
              <button
                type="button"
                className="chat-link"
                onClick={loadOlderMessages}
                disabled={isLoading}
              >
                {isLoading ? "Loading..." : "Load older messages"}
              </button>
            </div>
          )}

          {!isLoading && messages.length === 0 && activeConversation && (
            <div className="chat-thread-empty">
              <span className="chat-thread-empty-icon" aria-hidden="true">↔</span>
              <p>No messages yet. Say hello!</p>
            </div>
          )}

          {groupedMessages.map((item, idx) =>
            item.type === "date" ? (
              <div key={`date-${idx}`} className="chat-day">
                {item.label}
              </div>
            ) : (
              <div
                key={item.data.id}
                className={`chat-message ${item.data.senderId === user?.id ? "me" : "them"}`}
              >
                <div className="chat-bubble">
                  <p>{item.data.content}</p>
                  <span className="chat-time">{formatTime(item.data.createdAt)}</span>
                </div>
              </div>
            )
          )}

          {isOtherTyping && (
            <div className="chat-typing-indicator" data-testid="typing-indicator">
              {activeConversation?.otherUser?.fullName || "User"} is typing...
            </div>
          )}

          <div ref={endRef} />
        </div>

        {activeConversationId ? (
          <footer className="chat-input-area">
            {sendError && (
              <div className="chat-send-error">
                ⚠️ {sendError}
              </div>
            )}
            <input
              type="text"
              placeholder="Type a message..."
              aria-label="Message input"
              value={draft}
              onChange={handleInputChange}
              onKeyDown={handleKeyDown}
              disabled={sending}
            />
            <button
              type="button"
              className="chat-send-btn"
              onClick={handleSend}
              disabled={!draft.trim() || sending}
              aria-label="Send message"
            >
              {sending ? "..." : "Send"}
            </button>
          </footer>
        ) : (
          <footer className="chat-input-area chat-input-area-empty">
            <div className="chat-empty-state">
              <span className="chat-empty-icon" aria-hidden="true">✦</span>
              <p>Select a conversation to start messaging</p>
            </div>
          </footer>
        )}
      </div>
    </section>
  );
}

export default Chat;

﻿import React, { useState, useEffect } from "react";
import { Link, useParams, useNavigate } from "react-router-dom";
import { api } from "../services/api.js";
import ItemGallery from "../components/ItemGallery.jsx";
import ItemInfo from "../components/ItemInfo.jsx";
import BookingForm from "../components/BookingForm.jsx";
import PriceBreakdown from "../components/PriceBreakdown.jsx";
import { checkAvailability } from "../utils/bookingUtils.js";
import { useBookings } from "../context/BookingContext.jsx";
import { BOOKING_STATUS } from "../constants/bookingStatus.js";

function ItemDetails() {
  const { id } = useParams();
  const navigate = useNavigate();
  const { bookings } = useBookings();

  const [item, setItem] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [fetchError, setFetchError] = useState(null);

  const [startDate, setStartDate] = useState("");
  const [endDate, setEndDate] = useState("");
  const [error, setError] = useState("");

  useEffect(() => {
    let isMounted = true;
    const abortController = new AbortController();

    const fetchListing = async () => {
      try {
        setIsLoading(true);
        const response = await api.getListingById(id, abortController.signal);
        
        if (isMounted && response.success) {
          const apiItem = response.data;
          const mappedItem = {
            id: apiItem.id,
            title: apiItem.title,
            description: apiItem.description,
            category: apiItem.category,
            condition: apiItem.condition,
            pricePerDay: apiItem.dailyRentalRate,
            securityDeposit: apiItem.securityDeposit,
            mrp: apiItem.retailPrice,
            minimumRentalDays: apiItem.minimumRentalDays,
            location: apiItem.preferredPickupZone,
            images: apiItem.images && apiItem.images.length > 0 
              ? apiItem.images.map(img => img.imageUrl) 
              : ["purple"], 
            rating: apiItem.owner?.lenderRating || 4.8,
            reviewsCount: apiItem.owner?.ratingsCount || 0,
            ownerName: apiItem.owner?.fullName,
            ownerDept: apiItem.owner?.department,
            ownerImg: apiItem.owner?.profileImage,
            isVerified: true, 
            availability: apiItem.status === 'active' ? 'Available Now' : 'Not Available',
            dateAdded: apiItem.createdAt,
            isHidden: apiItem.status !== 'active'
          };
          setItem(mappedItem);
          setFetchError(null);
        }
      } catch (err) {
        if (err.name === 'AbortError') return;
        if (isMounted) {
          console.error("Failed to fetch live listing:", err);
          setFetchError(err.message || "Failed to load listing");
        }
      } finally {
        if (isMounted && !abortController.signal.aborted) {
          setIsLoading(false);
        }
      }
    };

    fetchListing();

    return () => {
      isMounted = false;
      abortController.abort();
    };
  }, [id]);

  if (isLoading) {
    return (
      <section className="page" style={{ minHeight: '60vh', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
        <p style={{ color: 'var(--muted)', fontSize: '18px' }}>Loading listing details...</p>
      </section>
    );
  }

  if (!item) {
    return (
      <section className="page" style={{ minHeight: '60vh', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center' }}>
        <h2 style={{ fontSize: '32px', marginBottom: '16px' }}>Item not found</h2>
        <p style={{ color: 'var(--muted)', marginBottom: '24px' }}>{fetchError || "The gear you are looking for doesn't exist or was removed."}</p>
        <button onClick={() => navigate('/marketplace')} className="btn primary">
          Back to Marketplace
        </button>
      </section>
    );
  }

  const calculateTotalDays = () => {
    if (!startDate || !endDate) return 0;
    const d1 = new Date(startDate);
    const d2 = new Date(endDate);
    d1.setHours(0, 0, 0, 0);
    d2.setHours(0, 0, 0, 0);
    const diffTime = d2.getTime() - d1.getTime();
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
    return diffDays >= 0 ? diffDays + 1 : 0;
  };

  const validateDates = (start, end) => {
    setError("");
    if (start && end) {
      const d1 = new Date(start);
      const d2 = new Date(end);
      d1.setHours(0, 0, 0, 0);
      d2.setHours(0, 0, 0, 0);
      if (d2 < d1) {
        setError("Return date cannot be before pickup date.");
        return false;
      }
      
      const activeBookings = bookings.filter(
        (b) => String(b.itemId) === String(item.id) && 
               (b.status === BOOKING_STATUS.approved || b.status === BOOKING_STATUS.itemGiven || b.status === BOOKING_STATUS.ongoing || b.status === BOOKING_STATUS.returnPending)
      );

      const availability = checkAvailability(start, end, activeBookings);
      if (!availability.isAvailable) {
        setError(`Item is already booked from ${availability.conflict.start} to ${availability.conflict.end}.`);
        return false;
      }
    }
    return true;
  };

  const handleStartChange = (val) => {
    setStartDate(val);
    validateDates(val, endDate);
  };

  const handleEndChange = (val) => {
    setEndDate(val);
    validateDates(startDate, val);
  };

  const totalDays = calculateTotalDays();
  const totalItemPrice = totalDays * item.pricePerDay;
  const serviceFee = totalDays > 0 ? 50 : 0;
  const finalTotal = totalItemPrice + serviceFee + (item.securityDeposit || 0);
  const isValid = totalDays > 0 && !error;

  const proceedToBooking = () => {
    navigate(`/booking/${item.id}`, { state: { startDate, endDate, from: 'details' } });
  };

  return (
    <section className="page" style={{ paddingTop: '24px' }}>
      
      {/* Back Navigation & Breadcrumbs */}
      <nav style={{ fontSize: '14px', color: 'var(--muted)', marginBottom: '24px', display: 'flex', alignItems: 'center', gap: '8px' }}>
        <button onClick={() => navigate(-1)} style={{ background: 'transparent', border: 'none', cursor: 'pointer', color: 'var(--primary)', fontWeight: 600, display: 'flex', alignItems: 'center', gap: '4px' }}>
          <span>â†</span> Back
        </button>
        <span>|</span>
        <Link to="/" style={{ textDecoration: 'none', color: 'inherit' }}>Home</Link>
        <span>&gt;</span>
        <Link to="/marketplace" style={{ textDecoration: 'none', color: 'inherit' }}>Marketplace</Link>
        <span>&gt;</span>
        <span style={{ color: 'var(--text)', fontWeight: 500 }}>{item.title}</span>
      </nav>

      <div className="item-details-layout" style={{ display: 'grid', gridTemplateColumns: 'minmax(0, 1fr) 400px', gap: '48px', alignItems: 'start' }}>
        
        {/* Left Section: Gallery & Info */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: '32px' }}>
          <ItemGallery images={item.images} fallbackClass={item.imageClass || item.images?.[0]} />
          <ItemInfo item={item} />
        </div>

        {/* Right Section: Sticky Booking Panel */}
        <div style={{ position: 'sticky', top: '100px', display: 'flex', flexDirection: 'column', gap: '24px' }}>
          <BookingForm 
            startDate={startDate} 
            endDate={endDate} 
            onStartChange={handleStartChange} 
            onEndChange={handleEndChange} 
            error={error} 
            totalDays={totalDays} 
          />
          <PriceBreakdown 
            totalDays={totalDays}
            pricePerDay={item.pricePerDay}
            securityDeposit={item.securityDeposit}
            serviceFee={serviceFee}
            finalTotal={finalTotal}
            isValid={isValid}
            onConfirm={proceedToBooking}
            primaryText="Request to Book"
          />
        </div>

      </div>
    </section>
  );
}

export default ItemDetails;

import React, { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext.jsx";
import { api } from "../services/api.js";

function Login() {
  const [showPassword, setShowPassword] = useState(false);
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleLogin = async (event) => {
    event.preventDefault();
    setError("");
    if (!email || !password) {
      setError("Email and password are required.");
      return;
    }

    if (!email.toLowerCase().endsWith("nitrr.ac.in")) {
      setError("Please login using your nitrr.ac.in campus email.");
      return;
    }

    try {
      setIsSubmitting(true);
      const response = await api.login({
        collegeEmail: email.trim().toLowerCase(),
        password
      });
      login(response.data);
      navigate("/marketplace");
    } catch (err) {
      setError(err.message || "Unable to login. Please try again.");
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <section className="auth-page">
      <div className="auth-tabs" role="tablist" aria-label="Authentication">
        <Link to="/login" className="auth-tab active" role="tab">
          Login
        </Link>
        <Link to="/signup" className="auth-tab" role="tab">
          Sign Up
        </Link>
      </div>

      <div className="auth-card">
        <div className="auth-header">
          <h1>Welcome back!</h1>
          <p>The campus marketplace is waiting for you.</p>
        </div>

        {error && (
          <div className="auth-error" style={{ color: '#ef4444', background: '#fee2e2', padding: '10px 14px', borderRadius: '8px', fontSize: '13px', marginBottom: '16px', border: '1px solid #f87171' }}>
            {error}
          </div>
        )}

        <form className="auth-form" onSubmit={handleLogin}>
          <label className="auth-label" htmlFor="login-email">
            Student Email
          </label>
          <div className="auth-field">
            <input
              id="login-email"
              type="email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              placeholder="name@university.edu"
              required
            />
          </div>

          <div className="auth-row">
            <label className="auth-label" htmlFor="login-password">
              Password
            </label>
            <span className="auth-link">Use your account password</span>
          </div>
          <div className="auth-field auth-password">
            <input
              id="login-password"
              type={showPassword ? "text" : "password"}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              placeholder="********"
              required
            />
            <span 
              className="auth-eye" 
              aria-hidden="true"
              onClick={() => setShowPassword(!showPassword)}
              style={{ cursor: "pointer", userSelect: "none" }}
            >
              {showPassword ? "Hide" : "Show"}
            </span>
          </div>

          <button className="btn primary auth-submit" type="submit" disabled={isSubmitting}>
            {isSubmitting ? "Signing In..." : "Enter the Hub"}
          </button>
        </form>
      </div>

      <div className="auth-features">
        <div className="auth-feature">
          <div className="auth-feature-icon">S</div>
          <div>
            <strong>Secure</strong>
            <span>Encrypted transactions</span>
          </div>
        </div>
        <div className="auth-feature">
          <div className="auth-feature-icon">C</div>
          <div>
            <strong>Community</strong>
            <span>Verified students only</span>
          </div>
        </div>
        <div className="auth-feature">
          <div className="auth-feature-icon">E</div>
          <div>
            <strong>Eco-friendly</strong>
            <span>Sharing reduces waste</span>
          </div>
        </div>
      </div>
    </section>
  );
}

