import React, { useState, useEffect, useMemo, useRef } from "react";
import { useSearchParams } from "react-router-dom";

const categories = [
  { name: "All" },
  { name: "Tech" },
  { name: "Books" },
  { name: "Adventure" },
  { name: "Sports" },
];

const locations = [
  "All Locations",
  "North Campus",
  "South Dorms",
  "Central Library",
  "Arts District",
];

const PAGE_SIZE = 8;

import { useListings } from "../context/ListingContext.jsx";
import ItemCard from "../components/ItemCard.jsx";
import { useBookings } from "../context/BookingContext.jsx";
import { BOOKING_STATUS } from "../constants/bookingStatus.js";

function Marketplace() {
  const [searchParams, setSearchParams] = useSearchParams();

  // Read all filter values from URL search params (canonical source)
  const activeCategory = searchParams.get("category") || "All";
  const activeLocation = searchParams.get("location") || "All Locations";
  const sortOption = searchParams.get("sort") || "Newest";
  const page = parseInt(searchParams.get("page") || "1", 10);

  // Local search input state for responsive typing; synced to URL via debounce
  const [searchQuery, setSearchQuery] = useState(searchParams.get("q") || "");

  const { marketplaceListings, isLoading, error, pagination, refreshListings } = useListings();
  const { bookings } = useBookings();

  // Ref to always have the latest searchParams available in debounce callback
  const searchParamsRef = useRef(searchParams);

  // Sync the ref after render so the debounce callback always reads current URL params
  useEffect(() => {
    searchParamsRef.current = searchParams;
  }, [searchParams]);

  // Ref to skip the initial effect call since ListingContext already fetches on mount
  const initialFetchDone = useRef(false);

  // Debounce search input → URL search params
  useEffect(() => {
    const handler = setTimeout(() => {
      const currentParams = searchParamsRef.current;
      const next = new URLSearchParams(currentParams);
      if (searchQuery) {
        next.set("q", searchQuery);
      } else {
        next.delete("q");
      }
      // Reset to page 1 when search changes
      next.delete("page");
      // Only update URL if the q param actually changed (prevents loops)
      if (next.get("q") !== currentParams.get("q")) {
        setSearchParams(next, { replace: true });
      }
    }, 300);
    return () => clearTimeout(handler);
  }, [searchQuery]); // eslint-disable-line react-hooks/exhaustive-deps

  // Sync local search input state when URL's q param changes externally
  useEffect(() => {
    setSearchQuery(searchParams.get("q") || "");
  }, [searchParams.get("q")]);

  // When filters in the URL change, re-fetch from backend
  useEffect(() => {
    if (!initialFetchDone.current) {
      initialFetchDone.current = true;
      // If there are URL params on initial mount, override the default empty fetch
      const hasParams = Array.from(searchParams.keys()).length > 0;
      if (!hasParams) return; // ListingContext already fetched with defaults
    }

    const controller = new AbortController();
    const params = {};
    const q = searchParams.get("q");
    const category = searchParams.get("category");
    const location = searchParams.get("location");
    const sort = searchParams.get("sort");
    const p = searchParams.get("page");

    if (q) params.q = q;
    if (category) params.category = category;
    if (location) params.location = location;
    if (sort === "Price: Low to High") params.sortBy = "price_asc";
    else if (sort === "Rating") params.sortBy = "rating";
    if (p) params.page = parseInt(p, 10);
    params.limit = PAGE_SIZE;

    refreshListings(controller.signal, params);
    return () => controller.abort();
  }, [searchParams, refreshListings]);

  // Helpers to update individual URL params
  const updateFilter = (key, value) => {
    const next = new URLSearchParams(searchParams);
    if (value === "All" || value === "All Locations" || !value) {
      next.delete(key);
    } else {
      next.set(key, value);
    }
    // Reset to page 1 on any filter change
    next.delete("page");
    setSearchParams(next, { replace: true });
  };

  const goToPage = (newPage) => {
    const next = new URLSearchParams(searchParams);
    if (newPage <= 1) {
      next.delete("page");
    } else {
      next.set("page", String(newPage));
    }
    setSearchParams(next, { replace: true });
  };

  // Apply ongoing booking overlays
  const displayListings = useMemo(() => {
    const ongoingByItemId = bookings
      .filter((booking) =>
        [BOOKING_STATUS.itemGiven, BOOKING_STATUS.ongoing, BOOKING_STATUS.returnPending].includes(booking.status)
      )
      .reduce((acc, booking) => {
        const itemId = String(booking.itemId);
        const current = acc[itemId];
        if (!current || new Date(booking.end) > new Date(current.end)) {
          acc[itemId] = booking;
        }
        return acc;
      }, {});

    return marketplaceListings
      .filter(item => !item.isHidden)
      .map((item) => ({
        ...item,
        rentedUntil: ongoingByItemId[String(item.id)]?.end || null,
      }));
  }, [bookings, marketplaceListings]);

  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const toggleSidebar = () => setIsSidebarOpen((o) => !o);

  const totalPages = pagination?.totalPages || 1;

  return (
    <section className="marketplace-container page">
      <div className="marketplace-top-bar">
        <div className="marketplace-search">
          <span role="img" aria-label="search">
            🔍
          </span>
          <input
            type="text"
            placeholder="Search for cameras, laptops, books..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
        </div>
        <button
          className="marketplace-filters-toggle btn secondary"
          onClick={toggleSidebar}
        >
          Filters <span>{isSidebarOpen ? "▲" : "▼"}</span>
        </button>
      </div>

      <div className="marketplace">
        <aside className={`marketplace-sidebar ${isSidebarOpen ? "open" : ""}`}>
          <div className="marketplace-panel">
            <div className="marketplace-panel-head">
              <span className="marketplace-panel-icon">C</span>
              <h4>Categories</h4>
            </div>
            <div className="marketplace-category-list">
              {categories.map((cat) => (
                <button
                  key={cat.name}
                  type="button"
                  onClick={() => updateFilter("category", cat.name)}
                  className={`marketplace-category ${
                    activeCategory === cat.name ? "active" : ""
                  }`}
                >
                  <span>{cat.name}</span>
                </button>
              ))}
            </div>
          </div>

          <div className="marketplace-panel">
            <h4>Pickup Location</h4>
            <div className="marketplace-location-list">
              {locations.map((loc) => (
                <label key={loc} className="marketplace-checkbox hover-target">
                  <input
                    type="radio"
                    name="location"
                    checked={activeLocation === loc}
                    onChange={() => updateFilter("location", loc === "All Locations" ? "" : loc)}
                  />
                  <span>{loc}</span>
                </label>
              ))}
            </div>
          </div>

          <div className="marketplace-panel">
            <h4>Sort By</h4>
            <select
              className="marketplace-sort-select"
              value={sortOption}
              onChange={(e) => updateFilter("sort", e.target.value)}
            >
              <option value="Newest">Newest</option>
              <option value="Price: Low to High">Price: Low to High</option>
              <option value="Rating">Rating</option>
            </select>
          </div>

          <div className="marketplace-perk">
            <h4>Campus Perk</h4>
            <p>Verified students get insurance on all rentals automatically.</p>
            <button className="btn outline" style={{width: '100%'}} type="button">
              Learn More
            </button>
          </div>
        </aside>

        <div className="marketplace-main">
          <div className="marketplace-head">
            <div>
              <h2>Explore Listings</h2>
              <p>
                Find high-quality gear you need for your next project or weekend
                trip, shared by peers.
              </p>
              {error && (
                <div style={{ marginTop: '12px', padding: '10px 16px', background: 'rgba(255,0,0,0.1)', color: 'red', borderRadius: '6px', fontSize: '14px', fontWeight: '500' }}>
                  ⚠️ {error}
                </div>
              )}
            </div>
          </div>

          <div className="marketplace-grid">
            {isLoading
              ? Array.from({ length: 6 }).map((_, index) => (
                  <div key={index} className="marketplace-card skeleton">
                    <div style={{ height: "170px" }}></div>
                    <div className="marketplace-card-body">
                      <div className="skeleton" style={{ height: "20px", width: "80%", marginBottom: "8px" }}></div>
                      <div className="skeleton" style={{ height: "16px", width: "50%" }}></div>
                      <div style={{ marginTop: "auto", paddingTop: "12px", display: "flex", justifyContent: "space-between" }}>
                        <div className="skeleton" style={{ height: "24px", width: "30%" }}></div>
                        <div className="skeleton" style={{ height: "24px", width: "20%" }}></div>
                      </div>
                      <div className="marketplace-card-actions">
                        <div className="skeleton" style={{ height: "40px", borderRadius: "8px" }}></div>
                        <div className="skeleton" style={{ height: "40px", borderRadius: "8px" }}></div>
                      </div>
                    </div>
                  </div>
                ))
              : displayListings.length > 0 ? (
                  displayListings.map((item) => (
                    <ItemCard key={item.id} item={item} />
                  ))
                ) : (
                  <div style={{ gridColumn: "1 / -1", textAlign: "center", padding: "40px 0", color: "var(--muted)" }}>
                    <h3>No listings found</h3>
                    <p>Try adjusting your search or filters.</p>
                  </div>
                )}
          </div>

          {/* Pagination Controls */}
          {pagination && totalPages > 1 && (
            <div style={{ display: 'flex', justifyContent: 'center', alignItems: 'center', gap: '12px', padding: '24px 0' }}>
              <button
                className="btn outline"
                style={{ padding: '8px 16px', fontSize: '14px' }}
                disabled={page <= 1}
                onClick={() => goToPage(page - 1)}
              >
                ← Previous
              </button>
              <span style={{ fontSize: '14px', color: 'var(--muted)' }}>
                Page {pagination.page} of {totalPages}
              </span>
              <button
                className="btn outline"
                style={{ padding: '8px 16px', fontSize: '14px' }}
                disabled={page >= totalPages}
                onClick={() => goToPage(page + 1)}
              >
                Next →
              </button>
            </div>
          )}
        </div>
      </div>
    </section>
  );
}

export default Marketplace;

import React, { useMemo, useState } from "react";
import BorrowedItemCard from "../components/BorrowedItemCard.jsx";
import UpcomingRentalCard from "../components/UpcomingRentalCard.jsx";
import CompletedRentalCard from "../components/CompletedRentalCard.jsx";
import PendingRequestCard from "../components/PendingRequestCard.jsx";
import { BOOKING_STATUS } from "../constants/bookingStatus.js";
import { useBookings } from "../context/BookingContext.jsx";

const tabs = ["Pending", "Active Rentals", "History"];


const formatShortDate = (value) => {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  return new Intl.DateTimeFormat("en-US", { month: "short", day: "2-digit" }).format(date);
};

const formatFullDate = (value) => {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  return new Intl.DateTimeFormat("en-US", { month: "short", day: "2-digit", year: "numeric" }).format(date);
};

const formatPickupDate = (value) => {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  return new Intl.DateTimeFormat("en-US", {
    month: "short",
    day: "2-digit",
    hour: "numeric",
    minute: "2-digit",
  }).format(date);
};

const formatRange = (start, end) => {
  if (!start && !end) return "";
  return `${formatShortDate(start)} - ${formatShortDate(end)}`;
};

const formatCurrency = (value) => {
  if (typeof value !== "number") return "";
  return new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 }).format(value);
};

const uniqueById = (items) => {
  const seen = new Set();
  return items.filter((item) => {
    const id = String(item?.id || "");
    if (!id || seen.has(id)) return false;
    seen.add(id);
    return true;
  });
};

function MyBookings() {
  const [activeTab, setActiveTab] = useState(tabs[0]);

  const { bookings, cancelBooking, confirmItemReceived, requestReturn } = useBookings();
  const handleComingSoon = () => {
    window.alert("Feature coming soon");
  };

  const { pending, activeRentals, history } = useMemo(() => {
    const normalized = uniqueById(bookings)
      .map((booking) => {
        const name = booking.title || "Item";
        const image = booking.image || "teal";
        const owner = booking.owner || "CampusRent Owner";
        const dates = formatRange(booking.start, booking.end);
        const submitted = formatFullDate(booking.submittedAt);
        const pickup = formatPickupDate(booking.pickupAt || booking.start);
        const returned = formatFullDate(booking.returnedAt || booking.end);
        const deposit = formatCurrency(booking.depositAmount);
        const total = formatCurrency(booking.totalAmount);
        const statusLabel =
          booking.status === BOOKING_STATUS.cancelled
            ? "Cancelled"
            : booking.status === BOOKING_STATUS.rejected
              ? "Rejected"
              : booking.status === BOOKING_STATUS.completed
                ? "Completed"
                : booking.status;
        const timelineAt = booking.cancelledAt || booking.returnedAt || booking.end || booking.submittedAt || "";
        return {
          id: booking.id,
          status: booking.status,
          statusLabel,
          cancelledBy: booking.cancelledBy || null,
          timelineAt,
          name,
          owner,
          dates,
          submitted,
          pickup,
          returned,
          deposit,
          total,
          image,
        };
      })
      .filter((booking) => booking.status);

    return {
      pending: normalized.filter((booking) => booking.status === BOOKING_STATUS.requested),
      activeRentals: normalized.filter((booking) =>
        [BOOKING_STATUS.approved, BOOKING_STATUS.itemGiven, BOOKING_STATUS.ongoing, BOOKING_STATUS.returnPending].includes(booking.status)
      ),
      history: normalized
        .filter((booking) =>
          [BOOKING_STATUS.completed, BOOKING_STATUS.cancelled, BOOKING_STATUS.rejected].includes(
            booking.status
          )
        )
        .sort((a, b) => new Date(b.timelineAt) - new Date(a.timelineAt)),
    };
  }, [bookings]);

  const stats = [
    { label: "Pending Requests", value: String(pending.length) },
    { label: "Active Rentals", value: String(activeRentals.length) },
    { label: "History Records", value: String(history.length) },
  ];

  return (
    <section style={{ display: "flex", flexDirection: "column", gap: "24px" }}>
      <div>
        <h1 style={{ fontSize: "32px", fontFamily: '"Space Grotesk", sans-serif', marginBottom: "8px" }}>
          My Borrowings
        </h1>
        <p style={{ color: "var(--muted, #6b7280)" }}>
          Track pending approvals, upcoming pickups, active borrowings, and completed returns.
        </p>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: "16px" }}>
        {stats.map((stat) => (
          <div
            key={stat.label}
            style={{
              padding: "18px",
              borderRadius: "16px",
              border: "1px solid var(--border, #e5e7eb)",
              background: "var(--surface, #ffffff)",
              boxShadow: "var(--shadow)",
            }}
          >
            <p style={{ margin: 0, color: "var(--muted, #6b7280)", fontSize: "14px" }}>{stat.label}</p>
            <h3 style={{ margin: "10px 0 0", fontSize: "24px", fontWeight: 700 }}>{stat.value}</h3>
          </div>
        ))}
      </div>

      <div style={{ display: "flex", gap: "12px", flexWrap: "wrap" }}>
        {tabs.map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className="btn"
            style={{
              padding: "10px 16px",
              borderRadius: "999px",
              border: "1px solid var(--border, #e5e7eb)",
              background: activeTab === tab ? "var(--primary, #0d9488)" : "transparent",
              color: activeTab === tab ? "#fff" : "var(--text-main, #1f2937)",
              fontWeight: 600,
            }}
          >
            {tab}
          </button>
        ))}
      </div>

      {activeTab === "Pending" && (
        <div style={{ display: "grid", gap: "16px" }}>
          {pending.map((request) => (
            <PendingRequestCard
              key={request.id}
              request={request}
              onCancel={async () => {
                try {
                  await cancelBooking(request.id);
                } catch (err) {
                  window.alert(err.message || "Failed to cancel booking.");
                }
              }}
              onMessageOwner={handleComingSoon}
            />
          ))}
        </div>
      )}

      {activeTab === "Active Rentals" && (
        <div style={{ display: "grid", gap: "16px" }}>
          {activeRentals.map((rental) => {
            if (rental.status === BOOKING_STATUS.approved) {
              return (
                <UpcomingRentalCard
                  key={rental.id}
                  rental={rental}
                  onCancel={async () => {
                    try {
                      await cancelBooking(rental.id);
                    } catch (err) {
                      window.alert(err.message || "Failed to cancel booking.");
                    }
                  }}
                  onChat={handleComingSoon}
                />
              );
            }

            const isItemGiven = rental.status === BOOKING_STATUS.itemGiven;
            const isOngoing = rental.status === BOOKING_STATUS.ongoing;
            const isReturnPending = rental.status === BOOKING_STATUS.returnPending;
            const primaryActionLabel = isItemGiven
              ? "Confirm Item Received"
              : isOngoing
                ? "Request Return"
                : "Return Requested";

            return (
              <BorrowedItemCard
                key={rental.id}
                rental={rental}
                primaryActionLabel={primaryActionLabel}
                primaryActionDisabled={isReturnPending}
                lifecycleNote={isReturnPending ? "Waiting for owner to confirm return." : ""}
                onPrimaryAction={async () => {
                  try {
                    if (isItemGiven) {
                      await confirmItemReceived(rental.id);
                    } else if (isOngoing) {
                      await requestReturn(rental.id);
                    }
                  } catch (err) {
                    window.alert(err.message || "Failed to update booking status.");
                  }
                }}
                onReportIssue={handleComingSoon}
                onChat={handleComingSoon}
              />
            );
          })}
        </div>
      )}

      {activeTab === "History" && (
        <div style={{ display: "grid", gap: "16px" }}>
          {history.map((rental) => (
            <CompletedRentalCard key={rental.id} rental={rental} onRateOwner={handleComingSoon} />
          ))}
        </div>
      )}
    </section>
  );
}

export default MyBookings;

import React, { useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import ListingCard from "../components/ListingCard.jsx";
import ApprovalCard from "../components/ApprovalCard.jsx";
import RentalHistoryCard from "../components/RentalHistoryCard.jsx";
import { BOOKING_STATUS } from "../constants/bookingStatus.js";
import { useBookings } from "../context/BookingContext.jsx";
import { useListings } from "../context/ListingContext.jsx";

const tabs = ["Active Listings", "Pending Approvals", "Rental History"];

const formatShortDate = (value) => {
  if (!value) return "";
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) return "";
  return new Intl.DateTimeFormat("en-US", { month: "short", day: "2-digit" }).format(date);
};

const formatRange = (start, end) => {
  if (!start && !end) return "";
  return `${formatShortDate(start)} - ${formatShortDate(end)}`;
};

const uniqueById = (items) => {
  const seen = new Set();
  return items.filter((item) => {
    const id = String(item?.id || "");
    if (!id || seen.has(id)) return false;
    seen.add(id);
    return true;
  });
};

function MyListings() {
  const navigate = useNavigate();
  const [activeTab, setActiveTab] = useState(tabs[0]);
  const { myListings, toggleHidden, deleteListing } = useListings();
  const { bookings, approveBooking, rejectBooking, cancelBooking, markItemGiven, confirmReturn } = useBookings();

  const formattedListings = useMemo(() => {
    return myListings.map((item) => {
      const itemBookings = uniqueById(
        bookings.filter((booking) => String(booking.itemId) === String(item.id))
      );
      const active = itemBookings.find((booking) =>
        [BOOKING_STATUS.itemGiven, BOOKING_STATUS.ongoing, BOOKING_STATUS.returnPending].includes(booking.status)
      );
      const upcoming = itemBookings.filter((booking) => booking.status === BOOKING_STATUS.approved);

      upcoming.sort((a, b) => new Date(a.start) - new Date(b.start));

      const nextReservation =
        upcoming.length > 0
          ? {
              dates: formatRange(upcoming[0].start, upcoming[0].end),
              renter: upcoming[0].requester || "Student",
            }
          : null;

      const status = active ? "Rented" : "Available";

      return {
        id: item.id,
        name: item.title,
        price: `Rs ${item.pricePerDay}`,
        status,
        isHidden: item.isHidden,
        image: item.images?.[0] || "teal",
        currentRental: active
          ? {
              id: active.id,
              dates: formatRange(active.start, active.end),
              renter: active.requester || "Student",
              status: active.status
            }
          : null,
        nextReservation,
        upcoming: upcoming.map((booking) => ({
          id: booking.id,
          dates: formatRange(booking.start, booking.end),
          renter: booking.requester || "Student",
          status: booking.status,
        })),
        rawItem: item,
      };
    });
  }, [myListings, bookings]);

  const approvals = useMemo(() => {
    const listingIds = new Set(myListings.map((listing) => String(listing.id)));
    return uniqueById(bookings)
      .filter(
        (booking) =>
          booking.status === BOOKING_STATUS.requested && listingIds.has(String(booking.itemId))
      )
      .map((booking) => {
        const item = myListings.find((listing) => String(listing.id) === String(booking.itemId));
        return {
          id: booking.id,
          title: item?.title || booking.title,
          requester: booking.requester || "CampusRent User",
          dates: formatRange(booking.start, booking.end),
        };
      });
  }, [bookings, myListings]);

  const history = useMemo(() => {
    const listingIds = new Set(myListings.map((listing) => String(listing.id)));
    return uniqueById(bookings)
      .filter(
        (booking) =>
          [BOOKING_STATUS.completed, BOOKING_STATUS.cancelled, BOOKING_STATUS.rejected].includes(
            booking.status
          ) && listingIds.has(String(booking.itemId))
      )
      .map((booking) => {
        const item = myListings.find((listing) => String(listing.id) === String(booking.itemId));
        const statusLabel =
          booking.status === BOOKING_STATUS.cancelled
            ? "Cancelled"
            : booking.status === BOOKING_STATUS.rejected
              ? "Rejected"
              : "Completed";
        const timelineAt =
          booking.cancelledAt || booking.returnedAt || booking.end || booking.submittedAt || "";

        return {
          id: booking.id,
          item: item?.title || booking.title || "Unspecified Item",
          renter: booking.requester || "CampusRent User",
          dates: formatRange(booking.start, booking.end),
          total: `Rs ${booking.totalAmount || 0}`,
          statusLabel,
          cancelledBy: booking.cancelledBy || null,
          timelineAt,
        };
      })
      .sort((a, b) => new Date(b.timelineAt) - new Date(a.timelineAt));
  }, [bookings, myListings]);

  const handleEditListing = (item) => {
    navigate(`/add?edit=${item.id}`);
  };

  const handleToggleHidden = (item) => {
    toggleHidden(item.id);
  };

  const handleDeleteListing = async (item) => {
    try {
      await deleteListing(item.id);
    } catch (err) {
      window.alert(err.message || "Failed to delete listing.");
    }
  };

  const handleApprove = async (approval) => {
    try {
      await approveBooking(approval.id);
    } catch (err) {
      window.alert(err.message || "Failed to approve booking.");
    }
  };

  const handleReject = async (approval) => {
    try {
      await rejectBooking(approval.id);
    } catch (err) {
      window.alert(err.message || "Failed to reject booking.");
    }
  };

  const handleConfirmReturn = async (item) => {
    const activeBooking = bookings.find((booking) => String(booking.id) === String(item.currentRental?.id));
    if (activeBooking) {
      try {
        await confirmReturn(activeBooking.id);
      } catch (err) {
        window.alert(err.message || "Failed to confirm return.");
      }
    }
  };

  const handleMarkItemGiven = async (bookingId) => {
    try {
      await markItemGiven(bookingId);
    } catch (err) {
      window.alert(err.message || "Failed to mark item as given.");
    }
  };

  const handleCancelUpcoming = async (bookingId) => {
    try {
      await cancelBooking(bookingId);
    } catch (err) {
      window.alert(err.message || "Failed to cancel booking.");
    }
  };

  return (
    <section style={{ display: "flex", flexDirection: "column", gap: "24px" }}>
      <div>
        <h1 style={{ fontSize: "32px", fontFamily: '"Space Grotesk", sans-serif', marginBottom: "8px" }}>
          My Gear Closet
        </h1>
        <p style={{ color: "var(--muted, #6b7280)" }}>
          Track your listings, approvals, and rental performance in one place.
        </p>
      </div>

      <div style={{ display: "grid", gridTemplateColumns: "repeat(auto-fit, minmax(220px, 1fr))", gap: "16px" }}>
        {[
          { label: "Active Listings", value: String(myListings.filter(l => !l.isHidden).length) },
          { label: "Pending Approvals", value: String(approvals.length) },
          { label: "History Records", value: String(history.length) },
        ].map((stat) => (
          <div
            key={stat.label}
            style={{
              padding: "18px",
              borderRadius: "16px",
              border: "1px solid var(--border, #e5e7eb)",
              background: "var(--surface, #ffffff)",
              boxShadow: "var(--shadow)",
            }}
          >
            <p style={{ margin: 0, color: "var(--muted, #6b7280)", fontSize: "14px" }}>{stat.label}</p>
            <h3 style={{ margin: "10px 0 0", fontSize: "24px", fontWeight: 700 }}>{stat.value}</h3>
          </div>
        ))}
      </div>

      <div style={{ display: "flex", gap: "12px", flexWrap: "wrap" }}>
        {tabs.map((tab) => (
          <button
            key={tab}
            onClick={() => setActiveTab(tab)}
            className="btn"
            style={{
              padding: "10px 16px",
              borderRadius: "999px",
              border: "1px solid var(--border, #e5e7eb)",
              background: activeTab === tab ? "var(--primary, #0d9488)" : "transparent",
              color: activeTab === tab ? "#fff" : "var(--text-main, #1f2937)",
              fontWeight: 600,
            }}
          >
            {tab}
          </button>
        ))}
      </div>

      {activeTab === "Active Listings" && (
        <div style={{ display: "grid", gap: "16px" }}>
          {formattedListings.map((item) => (
            <ListingCard
              key={item.id}
              item={item}
              onEdit={handleEditListing}
              onToggleHidden={handleToggleHidden}
              onDelete={handleDeleteListing}
              onConfirmReturn={handleConfirmReturn}
              onMarkItemGiven={handleMarkItemGiven}
              onCancelUpcoming={handleCancelUpcoming}
            />
          ))}
        </div>
      )}

      {activeTab === "Pending Approvals" && (
        <div style={{ display: "grid", gap: "16px" }}>
          {approvals.map((approval) => (
            <ApprovalCard
              key={approval.id}
              approval={approval}
              onApprove={handleApprove}
              onReject={handleReject}
            />
          ))}
        </div>
      )}

      {activeTab === "Rental History" && (
        <div style={{ display: "grid", gap: "16px" }}>
          {history.map((rental) => (
            <RentalHistoryCard key={rental.id} rental={rental} />
          ))}
        </div>
      )}
    </section>
  );
}

export default MyListings;

import React from "react";
import { Link } from "react-router-dom";

export default function NotFound() {
