const mockConversations = [
  {
    id: 'conv-1',
    bookingId: 'booking-1',
    otherUser: { id: 'user-2', fullName: 'Other User' },
    lastMessage: { content: 'Hello!', createdAt: new Date().toISOString(), senderId: 'user-2' },
    unreadCount: 3,
  },
  {
    id: 'conv-2',
    bookingId: 'booking-2',
    otherUser: { id: 'user-3', fullName: 'Third User' },
    lastMessage: null,
    unreadCount: 0,
  },
];

function UnreadConsumer() {
  const chat = useChat();
  return (
    <div>
      <div data-testid="unread-counts">{JSON.stringify(chat.unreadCounts)}</div>
      <div data-testid="active-conversation-id">{chat.activeConversationId || 'none'}</div>
      <button
        data-testid="select-conv"
        onClick={() => chat.selectConversation('conv-1')}
      >
        Select Conv 1
      </button>
      <ul>
        {chat.conversations.map((c) => (
          <li key={c.id} data-testid={`conv-${c.id}`}>
            {c.otherUser?.fullName}
            {(chat.unreadCounts[c.id] || 0) > 0 && (
              <span data-testid={`badge-${c.id}`} className="chat-unread-badge">
                {chat.unreadCounts[c.id]}
              </span>
            )}
          </li>
        ))}
      </ul>
    </div>
  );
}

describe('Unread Badge', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    api.getMyConversations.mockResolvedValue({
      success: true,
      data: mockConversations,
    });
    api.getConversationMessages.mockResolvedValue({
      success: true,
      data: [],
      hasMore: false,
      nextCursor: null,
    });
    api.markConversationRead.mockResolvedValue({
      success: true,
      data: { unreadCount: 0 },
    });
  });

  it('should render unread badge when unreadCount > 0', async () => {
    renderWithProviders(<UnreadConsumer />);

    await waitFor(() => {
      expect(screen.getByTestId('badge-conv-1')).toBeDefined();
    });

    const badge = screen.getByTestId('badge-conv-1');
    expect(badge.textContent).toBe('3');
  });

  it('should NOT render badge when unreadCount is 0', async () => {
    renderWithProviders(<UnreadConsumer />);

    await waitFor(() => {
      expect(api.getMyConversations).toHaveBeenCalled();
    });

    const badge = screen.queryByTestId('badge-conv-2');
    expect(badge).toBeNull();
  });

  it('should clear unread badge when conversation is selected', async () => {
    renderWithProviders(<UnreadConsumer />);

    await waitFor(() => {
      expect(screen.getByTestId('badge-conv-1')).toBeDefined();
    });

    const selectBtn = screen.getByTestId('select-conv');
    await act(async () => {
      fireEvent.click(selectBtn);
    });

    await waitFor(() => {
      expect(api.markConversationRead).toHaveBeenCalledWith('conv-1');
    });

    const badgeAfter = screen.queryByTestId('badge-conv-1');
    expect(badgeAfter).toBeNull();
  });

  it('should update unread counts from API response on mount', async () => {
    renderWithProviders(<UnreadConsumer />);

    await waitFor(() => {
      const el = screen.getByTestId('unread-counts');
      const counts = JSON.parse(el.textContent);
      expect(counts['conv-1']).toBe(3);
      expect(counts['conv-2']).toBe(0);
    });
  });

  it('should track unreadCounts as an object', async () => {
    renderWithProviders(<UnreadConsumer />);

    await waitFor(() => {
      const el = screen.getByTestId('unread-counts');
      const counts = JSON.parse(el.textContent);
      expect(typeof counts).toBe('object');
      expect(counts).not.toBeNull();
    });
  });
});

import React from 'react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { AuthProvider, useAuth } from '../../context/AuthContext';

// Test consumer component that exposes auth state
function TestConsumer() {
  const { user, login, logout } = useAuth();
  return (
    <div>
      <p data-testid="auth-state">{user ? `Logged in as ${user.fullName}` : 'Not logged in'}</p>
      <button data-testid="btn-login" onClick={() => login({ user: { fullName: 'Alex Rivera' }, token: 'fake-token' })}>
        Login
      </button>
      <button data-testid="btn-logout" onClick={logout}>
        Logout
      </button>
    </div>
  );
}

function renderWithProvider() {
  return render(
    <AuthProvider>
      <TestConsumer />
    </AuthProvider>
  );
}

describe('AuthContext', () => {
  beforeEach(() => {
    localStorage.clear();
  });

  it('starts with null user when nothing in localStorage', () => {
    renderWithProvider();
    expect(screen.getByTestId('auth-state').textContent).toBe('Not logged in');
  });

  it('sets user after login is called', async () => {
    const user = userEvent.setup();
    renderWithProvider();
    await user.click(screen.getByTestId('btn-login'));
    expect(screen.getByTestId('auth-state').textContent).toBe('Logged in as Alex Rivera');
  });

  it('persists user to localStorage on login', async () => {
    const user = userEvent.setup();
    renderWithProvider();
    await user.click(screen.getByTestId('btn-login'));
    const stored = JSON.parse(localStorage.getItem('campusRent_user'));
    expect(stored.fullName).toBe('Alex Rivera');
  });

  it('persists token to localStorage on login', async () => {
    const user = userEvent.setup();
    renderWithProvider();
    await user.click(screen.getByTestId('btn-login'));
    expect(localStorage.getItem('campusRent_token')).toBe('fake-token');
  });

  it('clears user after logout', async () => {
    const testUser = userEvent.setup();
    renderWithProvider();
    await testUser.click(screen.getByTestId('btn-login'));
    expect(screen.getByTestId('auth-state').textContent).toBe('Logged in as Alex Rivera');
    await testUser.click(screen.getByTestId('btn-logout'));
    expect(screen.getByTestId('auth-state').textContent).toBe('Not logged in');
  });

  it('clears localStorage on logout', async () => {
    const testUser = userEvent.setup();
    renderWithProvider();
    await testUser.click(screen.getByTestId('btn-login'));
    await testUser.click(screen.getByTestId('btn-logout'));
    expect(localStorage.getItem('campusRent_user')).toBeNull();
    expect(localStorage.getItem('campusRent_token')).toBeNull();
  });

  it('ignores login call with missing data', async () => {
    const testUser = userEvent.setup();
    renderWithProvider();
    // Login with empty object should be ignored because user data is missing
    const loginButton = screen.getByTestId('btn-login');
    // Re-render to verify state persists as not logged in
    expect(screen.getByTestId('auth-state').textContent).toBe('Not logged in');
  });

  it('restores user from localStorage on mount', () => {
    localStorage.setItem('campusRent_user', JSON.stringify({ fullName: 'Samira Patel' }));
    localStorage.setItem('campusRent_token', 'existing-token');
    renderWithProvider();
    expect(screen.getByTestId('auth-state').textContent).toBe('Logged in as Samira Patel');
  });

  it('throws error when useAuth is used outside AuthProvider', () => {
    // Suppress console.error for this expected error
    const consoleSpy = vi.spyOn(console, 'error').mockImplementation(() => {});
    expect(() => render(<TestConsumer />)).toThrow();
    consoleSpy.mockRestore();
  });
});
